mapper.select:
SELECT c.*, m.code AS material_code, m.name AS material_name, m.spec, m.unit, m.category FROM fin_material_cost c JOIN wms_material m ON m.id = c.material_id WHERE c.period = #{period}
AND (m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.code
